// MapCreateBulk creates a bulk creation builder from the given slice. For each item in the slice, the function creates
// a builder and applies setFunc on it.
func (c *AcademicSessionClient) MapCreateBulk(slice any, setFunc func(*AcademicSessionCreate, int)) *AcademicSessionCreateBulk {
	rv := reflect.ValueOf(slice)
	if rv.Kind() != reflect.Slice {
		return &AcademicSessionCreateBulk{err: fmt.Errorf("calling to AcademicSessionClient.MapCreateBulk with wrong type %T, need slice", slice)}
	}
	builders := make([]*AcademicSessionCreate, rv.Len())
	for i := 0; i < rv.Len(); i++ {
		builders[i] = c.Create()
		setFunc(builders[i], i)
	}
	return &AcademicSessionCreateBulk{config: c.config, builders: builders}
}

