// QueryPreviousSession queries the previous_session edge of a AcademicSession.
func (c *AcademicSessionClient) QueryPreviousSession(_m *AcademicSession) *AcademicSessionQuery {
	query := (&AcademicSessionClient{config: c.config}).Query()
	query.path = func(context.Context) (fromV *sql.Selector, _ error) {
		id := _m.ID
		step := sqlgraph.NewStep(
			sqlgraph.From(academicsession.Table, academicsession.FieldID, id),
			sqlgraph.To(academicsession.Table, academicsession.FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, academicsession.PreviousSessionTable, academicsession.PreviousSessionColumn),
		)
		fromV = sqlgraph.Neighbors(_m.driver.Dialect(), step)
		return fromV, nil
	}
	return query
}

// QueryNextSessions queries the next_sessions edge of a AcademicSession.
